# --- patch index.html (idempotent; keeps existing logos/design) ---
s=open(P+'index.html',encoding='utf8').read()
if 'cookies.js' not in s:
    def rep(a,b):
        global s
        assert a in s,a[:40];s=s.replace(a,b)
    rep('</style>','.lk{background:none;border:0;color:#fff;text-decoration:underline;font:inherit;cursor:pointer;padding:0}.note{font-size:.9rem;color:var(--mut);margin:12px 0 0}.doc{max-width:820px;padding:48px 20px 80px}.doc h2{font-size:1.4rem;margin-top:36px}.doc li{margin:6px 0}.draft{border:1px solid var(--ln);background:#fff;border-radius:12px;padding:16px;margin-top:40px}footer a:focus-visible,.lk:focus-visible{outline-color:#00e5ff}</style>')
    rep('<p><a href="#about">אודות</a> · <a href="#lead">צור קשר</a></p>','<p><a href="#about">אודות</a> · <a href="#lead">צור קשר</a> · <a href="/privacy.html">מדיניות פרטיות</a> · <a href="/terms.html">תנאי שימוש</a> · <a href="/accessibility.html">הצהרת נגישות</a> · <button type="button" class="lk" data-cookie-settings>הגדרות Cookies</button></p>')
    rep('<div id="msg" role="status" aria-live="polite" tabindex="-1"></div></form>','<div id="msg" role="status" aria-live="polite" tabindex="-1"></div><p class="note">בשליחת הטופס אני מאשר/ת שקראתי את <a href="/privacy.html">מדיניות הפרטיות</a>.</p></form>')
    rep('<script src="/app.js"></script>','<script src="/app.js"></script><script src="/cookies.js"></script>')
    open(P+'index.html','w',encoding='utf8').write(s)
css=re.search(r'<style>(.*?)</style>',s,re.S).group(1)
HEAD='''<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{t} | חיבור ישיר</title><meta name="description" content="{t} של חיבור ישיר."><link rel="canonical" href="/{f}"><link rel="icon" href="/favicon.png" type="image/png"><style>{css}</style></head><body>
<a class="skip" href="#main">דלג לתוכן הראשי</a>
<header class="s"><div class="w bar"><a class="logo" href="/"><img src="/logo.webp" alt="חיבור ישיר - לדף הבית" width="720" height="178" style="height:48px;width:auto;display:block"></a><button id="mb" aria-expanded="false" aria-controls="nv">תפריט</button>
<nav id="nv" aria-label="ראשי"><a href="/">ראשי</a><a href="/#services">השירותים שלנו</a><a href="/#how">איך זה עובד</a><a href="/#reviews">לקוחות מספרים</a><a href="/#about">אודות</a><a href="/#faq">שאלות נפוצות</a><a href="/#lead">צור קשר</a></nav><a class="btn" href="/#lead">בדיקת חיסכון</a></div></header>
<main id="main" class="doc"><h1 style="font-size:clamp(2rem,5vw,3rem)">{t}</h1><p><small>עודכן לאחרונה: <time>{u}</time></small></p>'''
CONTACT='<p><b>חיבור ישיר</b><br>טלפון: <a href="tel:0522096409">052-209-6409</a><br>אימייל: <a href="mailto:chiburyashir@gmail.com">chiburyashir@gmail.com</a><br>כתובת: נועם אלימלך 27, ביתר עילית</p>'
def page(f,t,body,draft):
    d=f'<p class="draft">{draft}</p>' if draft else ''
    open(P+f,'w',encoding='utf8').write(HEAD.format(t=t,f=f,css=css,u=UPDATED)+body+d+'</main>'+FOOT.format(r='/')+'<script src="/sub.js"></script><script src="/cookies.js"></script></body></html>')
def sec(*a):
    return ''.join(f'<h2>{h}</h2>{b}' for h,b in zip(a[::2],a[1::2]))
ul=lambda *i:'<ul>'+''.join(f'<li>{x}</li>' for x in i)+'</ul>'
page('privacy.html','מדיניות פרטיות',sec(
'מי מפעיל את האתר','<p>האתר מופעל על ידי חיבור ישיר ("אנחנו"). אנחנו עוזרים ללקוחות פרטיים ולעסקים לבדוק את שירותי התקשורת שלהם. מסמך זה מסביר איזה מידע אנחנו אוספים באתר, למה, ומה הזכויות שלכם.</p>',
'איזה מידע נאסף','<p>כשאתם ממלאים את טופס יצירת הקשר, אנחנו שומרים:</p>'+ul('שם פרטי ושם משפחה','מספר טלפון','כתובת אימייל, אם בחרתם למסור','סוג השירות שביקשתם (סלולר, אינטרנט / פייבר, טלוויזיה או אחר)','הסכמה ליצירת קשר, ומועד מתן ההסכמה','הסכמה לקבלת מידע שיווקי, אם ניתנה','מועד הפנייה ומקורה (האתר)')+'<p>איננו מבקשים באתר מידע שאינו נחוץ לטיפול בפנייה.</p>',
'למה אנחנו משתמשים במידע',ul('יצירת קשר איתכם וטיפול בפנייה','התאמת שירותים ובדיקת אפשרויות מתאימות','ניהול הפניות (לידים) והמעקב אחריהן','שליחת מידע שיווקי – רק אם נתתם לכך הסכמה נפרדת')+'<p>ההסכמה לקבלת מידע שיווקי היא רשות. היא אינה מסומנת מראש, ושליחת הטופס אינה מותנית בה.</p>',
'האם חובה למסור מידע','<p>שם, טלפון, סוג השירות ואישור יצירת קשר נדרשים כדי שנוכל לחזור אליכם. אימייל והסכמה שיווקית הם בחירה שלכם. אין חובה חוקית למסור מידע, אך בלי השדות הנדרשים לא נוכל לטפל בפנייה.</p>',
'ספקי שירות חיצוניים','<p>לצורך תפעול האתר והטיפול בפניות אנו עשויים להשתמש בספקי שירות, כגון: Google Sheets / Google Workspace לניהול רשימת הפניות, שירות דואר אלקטרוני לשליחת התראות פנימיות, שירותי אחסון (Hosting), וכן כלי אנליטיקה או מערכות ניהול. ספקים אלה מקבלים מידע רק במידה הנדרשת למתן השירות. חלק מהם עשויים לאחסן מידע מחוץ לישראל.</p>',
'שמירת המידע ואבטחתו','<p>המידע נשמר במסד נתונים מאובטח, והגישה אליו מוגבלת למורשים בלבד ומחייבת הזדהות. פרטי גישה לשירותים חיצוניים נשמרים בצד השרת בלבד. אנחנו שומרים את המידע כל עוד הוא נחוץ למטרות שתוארו או כנדרש בדין, ולאחר מכן מוחקים אותו או הופכים אותו לאנונימי. אין שיטת אבטחה שהיא מושלמת, ולכן איננו יכולים להבטיח הגנה מוחלטת.</p>',
'Cookies וטכנולוגיות מעקב','<p>האתר משתמש בטכנולוגיות הכרחיות לתפקודו. אנליטיקה ושיווק (כגון Google Analytics, Google Ads או Meta Pixel) יופעלו, אם יופעלו, רק לאחר שנתתם הסכמה. בכל רגע אפשר לשנות את הבחירה דרך "הגדרות Cookies" בתחתית האתר.</p>',
'הזכויות שלכם','<p>לפי הדין החל, אתם רשאים לבקש לעיין במידע שנשמר עליכם, לתקן אותו או לבקש למחוק אותו. אפשר גם לבטל בכל עת הסכמה לקבלת מידע שיווקי. נטפל בבקשות בהתאם לדין, ויתכנו מקרים שבהם נהיה מחויבים לשמור חלק מהמידע.</p>',
'יצירת קשר בנושא פרטיות','<p>לכל שאלה או בקשה בנושא פרטיות:</p>'+CONTACT,
'שינויים במדיניות','<p>נעדכן מסמך זה מעת לעת. התאריך העדכני מופיע בראש העמוד.</p>'),
'מסמך זה מהווה טיוטת מדיניות ויש לבצע בדיקה משפטית סופית בהתאם לפעילות העסק בפועל.')
page('terms.html','תנאי שימוש',sec(
'פרטי העסק','<p>האתר מופעל על ידי חיבור ישיר.</p>'+CONTACT,
'מטרת האתר ואופי השירות','<p>האתר מספק מידע על שירותי חיבור ישיר ומאפשר להשאיר פרטים כדי שנציג יחזור אליכם לבדיקת שירותי התקשורת שלכם. השירות הוא בדיקה והתאמה, והוא אינו מחליף את הסכם ההתקשרות מול ספק התקשורת.</p>',
'מה איננו מבטיחים',ul('השירות אינו מבטיח חיסכון קבוע או סכום חיסכון מסוים','השירות אינו מבטיח קליטה, מהירות או זמינות של תשתית מסוימת בכל מקום','הצעות, מחירים ומבצעים של ספקים עשויים להשתנות','המידע באתר אינו מחליף את תנאי ההתקשרות הרשמיים של ספקי התקשורת'),
'אחריות המשתמש','<p>אתם מתבקשים למסור פרטים נכונים ומדויקים, כדי שנוכל לחזור אליכם ולטפל בפנייה.</p>',
'שימוש מותר ואסור','<p>מותר להשתמש באתר למטרות אישיות או עסקיות לגיטימיות לבדיקת שירותי תקשורת. אסור למסור פרטים כוזבים או פרטים של אחר ללא רשותו, לשלוח פניות אוטומטיות או מטרידות, לנסות לפגוע באבטחת האתר או בתפקודו, או להעתיק את תוכנו שלא כדין.</p>',
'קניין רוחני','<p>התכנים, העיצוב, הלוגו והשם "חיבור ישיר" שייכים לחיבור ישיר או לבעלי הזכויות בהם. אין להעתיקם או להשתמש בהם ללא אישור מראש ובכתב, אלא בהתאם לדין.</p>',
'פרטיות ואבטחת מידע','<p>אופן הטיפול במידע אישי מפורט ב<a href="/privacy.html">מדיניות הפרטיות</a>. אנו נוקטים אמצעים סבירים לאבטחת האתר והמידע, אך לא ניתן להבטיח אבטחה מוחלטת.</p>',
'נגישות','<p>אנו פועלים להנגשת האתר. ראו <a href="/accessibility.html">הצהרת הנגישות</a>.</p>',
'קישורים לאתרים חיצוניים','<p>ייתכנו באתר קישורים לאתרים חיצוניים, כגון WhatsApp. איננו אחראים לתוכנם או לתנאי השימוש שלהם.</p>',
'שינויים באתר ובתנאים','<p>אנו רשאים לשנות את האתר, את השירותים המוצגים בו ואת תנאי השימוש. הנוסח העדכני יפורסם בעמוד זה.</p>',
'דין חל','<p>על תנאים אלה יחול הדין הישראלי. אין באמור כדי לפגוע בזכויות שהדין מקנה לצרכנים ושאין אפשרות להתנות עליהן.</p>',
'יצירת קשר',CONTACT),
'תנאים אלה מהווים טיוטה ויש לבצע בדיקה משפטית סופית לפני פרסום האתר.')
page('accessibility.html','הצהרת נגישות',sec(
'','<p>חיבור ישיר רואה חשיבות רבה במתן שירות שוויוני ונגיש לכלל המשתמשים ופועלת להנגשת אתר האינטרנט שלה לאנשים עם מוגבלות.</p><p>האתר תוכנן תוך התייחסות לדרישות הנגישות החלות בישראל, ובהן תקנות שוויון זכויות לאנשים עם מוגבלות (התאמות נגישות לשירות) והתקן הישראלי ת"י 5568, ברמה הרלוונטית. נכון למועד העדכון לא בוצעה בדיקת נגישות מקצועית מלאה, ולכן איננו מצהירים על עמידה מלאה בתקן.</p>',
'התאמות שבוצעו באתר',ul('ניווט מלא באמצעות מקלדת, וסדר Tab הגיוני','סימון Focus ברור לכל רכיב אינטראקטיבי','קישור "דלג לתוכן הראשי" בראש כל עמוד','מבנה כותרות תקין, עם כותרת ראשית אחת בכל עמוד','תוויות (Labels) לכל שדות הטפסים, והודעות שגיאה שמוקראות לקוראי מסך','טקסט חלופי (Alt) לתמונות משמעותיות','ניגודיות צבעים מותאמת, ואי-הסתמכות על צבע בלבד להעברת מידע','תאימות לקוראי מסך באמצעות HTML סמנטי ותכונות ARIA','תצוגה מותאמת למובייל, ללא גלילה אופקית','כיווניות RTL ושפת עמוד עברית','אפשרות הגדלת טקסט באמצעות הדפדפן (Zoom) ללא שבירת התצוגה','כיבוד ההגדרה prefers-reduced-motion להפחתת אנימציות'),
'ניווט במקלדת','<p>Tab מעביר בין רכיבים, Shift+Tab חוזר אחורה, Enter ו-Space מפעילים כפתורים וקישורים, ו-Escape סוגר את התפריט במובייל ואת חלון ה-Cookies.</p>',
'נתקלתם בבעיית נגישות?','<p>אם נתקלתם בקושי בעת השימוש באתר, נשמח שתעדכנו אותנו כדי שנוכל לבדוק ולטפל בנושא. כדאי לציין את כתובת העמוד ואת סוג הקושי.</p>',
'פרטי יצירת קשר',CONTACT),
'')
